#include <array>
#include <iostream>

int main() {
    constexpr std::array<std::array<int, 2>, 3> matrix{{{{1, 2}}, {{3, 4}}, {{5, 6}}}};
    for (std::size_t col = 0; col < 2; ++col) {
        for (std::size_t row = 0; row < 3; ++row) std::cout << matrix[row][col] << ' ';
        std::cout << '\n';
    }
}
